-- Promote the frozen Heist 0.3/client-v5 Listing to fresh hosted formation.
-- The prior 0.4 Listing remains immutable and addressable for retained Runs.

do $revision$
declare
  expected_document constant bytea := decode($listing$$listing$, 'base64');
  expected_value constant jsonb := convert_from(expected_document, 'utf8')::jsonb;
begin
  insert into platform_store.activity_listing_revisions (
    listing_revision_digest, listing_key, canonical_document, pack_revision_digest,
    client_release_digest, client_surface_id, catalog_visibility, creator_access,
    public_viewing_policy, result_publication_policy, result_projector_revision_digest,
    public_projection_schema, public_projection_schema_digest, result_output_schema,
    result_output_schema_digest, result_canonicalizer_version, result_output_max_bytes,
    room_setup_configuration, seat_templates, allow_multiple_seats_per_account,
    pre_start_deadline_seconds
  ) values (
    'blake3:a12a29ad0382c7053a14295a60d017fbdc817c24e513521f85be982f5ec07dfc',
    'worldstream.agent-heist.house-preview', expected_document,
    expected_value #>> '{pack,digest}', expected_value #>> '{client,release_digest}',
    expected_value #>> '{client,surface_id}', expected_value #>> '{catalog,visibility}',
    expected_value ->> 'creator_access', expected_value ->> 'public_viewing_policy',
    expected_value #>> '{result,publication,policy}', expected_value #>> '{result,projector,digest}',
    expected_value #>> '{result,projection,schema}', expected_value #>> '{result,projection,digest}',
    'worldstream/result-summary/v1',
    'blake3:816295fc5ac531886f090e59de24901633a60ed68af1510e133cead3d7eb35c6',
    'worldstream/canonical-json/v1', 4096,
    expected_value #> '{room_setup,configuration}', expected_value -> 'seats', false, 1800
  ) on conflict (listing_revision_digest) do nothing;

  if not exists (
    select 1 from platform_store.activity_listing_revisions retained
    where retained.listing_revision_digest = 'blake3:a12a29ad0382c7053a14295a60d017fbdc817c24e513521f85be982f5ec07dfc'
      and retained.canonical_document = expected_document
  ) then
    raise exception using errcode = '23505', message = 'hosted_heist_0_3_listing_identity_conflict';
  end if;
end;
$revision$;
